create extension if not exists pgcrypto;
create type public.account_status as enum ('pending','active','locked','suspended','deactivated');
create type public.verification_status as enum ('self_declared','pending','verified','expired','unable_to_verify');
create type public.membership_status as enum ('invited','active','suspended','revoked','left');
create table public.user_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null check(char_length(trim(full_name)) between 2 and 160),mobile_number text,account_status public.account_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.professional_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.user_profiles(id) on delete cascade,adr_professional_id text unique,public_display_name text,professional_bio text,city text,state text,country text not null default 'India',profile_visibility boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.capability_types(id smallint generated always as identity primary key,code text not null unique,display_name text not null unique,is_active boolean not null default true);
insert into public.capability_types(code,display_name) values ('arbitrator','Arbitrator'),('mediator','Mediator'),('conciliator','Conciliator'),('advocate','Advocate'),('law_firm_member','Law Firm Member'),('corporate_legal','Corporate Legal Professional'),('tribunal_secretary','Tribunal Secretary'),('service_provider','Service Provider'),('party','Party') on conflict do nothing;
create table public.user_capabilities(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.user_profiles(id) on delete cascade,capability_type_id smallint not null references public.capability_types(id),verification_status public.verification_status not null default 'self_declared',effective_from date not null default current_date,effective_to date,created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from));
create index user_capabilities_user_idx on public.user_capabilities(user_id);
create table public.institution_affiliations(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.user_profiles(id) on delete cascade,institution_name text not null,designation text,verification_status public.verification_status not null default 'self_declared',effective_from date,effective_to date,evidence_reference text,created_at timestamptz not null default now(),check(effective_to is null or effective_from is null or effective_to>=effective_from));
create table public.matters(id uuid primary key default gen_random_uuid(),matter_code text not null unique,matter_title text not null check(char_length(trim(matter_title)) between 2 and 250),proceeding_type text not null check(proceeding_type in('arbitration','mediation','conciliation','other_adr')),appointment_route text not null check(appointment_route in('institutional','court_appointed','mutual_appointment','party_appointed','other')),institution_name text,created_by uuid not null references public.user_profiles(id),matter_status text not null default 'draft' check(matter_status in('draft','active','on_hold','closed','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.matter_memberships(id uuid primary key default gen_random_uuid(),matter_id uuid not null references public.matters(id) on delete restrict,user_id uuid not null references public.user_profiles(id) on delete restrict,membership_status public.membership_status not null default 'invited',invited_by uuid references public.user_profiles(id),invited_at timestamptz not null default now(),accepted_at timestamptz,effective_from timestamptz,effective_to timestamptz,created_at timestamptz not null default now(),check(effective_to is null or effective_from is null or effective_to>=effective_from));
create unique index one_active_membership_per_user_matter on public.matter_memberships(matter_id,user_id) where membership_status in('invited','active','suspended');
create index matter_memberships_user_idx on public.matter_memberships(user_id);
create table public.roles(id smallint generated always as identity primary key,code text not null unique,display_name text not null unique);
insert into public.roles(code,display_name) values ('sole_arbitrator','Sole Arbitrator'),('presiding_arbitrator','Presiding Arbitrator'),('co_arbitrator','Co-Arbitrator'),('mediator','Mediator'),('claimant','Claimant'),('respondent','Respondent'),('claimant_advocate','Claimant Advocate'),('respondent_advocate','Respondent Advocate'),('tribunal_secretary','Tribunal Secretary'),('institution_case_manager','Institutional Case Manager'),('typist','Typist'),('service_provider','Service Provider') on conflict do nothing;
create table public.matter_member_roles(id uuid primary key default gen_random_uuid(),membership_id uuid not null references public.matter_memberships(id) on delete restrict,role_id smallint not null references public.roles(id),assigned_by uuid not null references public.user_profiles(id),authority_reference text,effective_from timestamptz not null default now(),effective_to timestamptz,is_active boolean not null default true,created_at timestamptz not null default now(),check(effective_to is null or effective_to>=effective_from));
create table public.audit_events(id uuid primary key default gen_random_uuid(),actor_user_id uuid references public.user_profiles(id),event_type text not null,entity_type text not null,entity_id uuid,event_summary text not null,created_at timestamptz not null default now());
create index audit_events_created_idx on public.audit_events(created_at desc);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.user_profiles(id,full_name,account_status) values(new.id,coalesce(nullif(trim(new.raw_user_meta_data->>'full_name'),''),'New user'),'pending') on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
